corrected_code:
const { Queue } = require('bullmq');
const transcodeQueue = new Queue('transcode-pipeline', { connection: redisConfig });

app.post('/api/media/transcode/:jobId/cancel', requireAuth, async (req, res) => {
  const job = await transcodeQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).send('Job not found');
  if (job.data.ownerId !== req.user.id) {
    return res.status(403).send('Forbidden: cannot cancel transcode jobs of other users');
  }
  await job.discard();
  await job.moveToFailed(new Error('Canceled by user'), true);
  res.json({ canceled: true, jobId: job.id });
});
